import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BsgK4TUM.js";const p=JSON.parse('{"title":"Multilingual Setup","description":"","frontmatter":{},"headers":[],"relativePath":"how-tos/multilingual.md","filePath":"how-tos/multilingual.md"}'),l={name:"how-tos/multilingual.md"};function i(s,e,r,u,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="multilingual-setup" tabindex="-1">Multilingual Setup <a class="header-anchor" href="#multilingual-setup" aria-label="Permalink to &quot;Multilingual Setup&quot;">​</a></h1><p>Community Store is aware of multilingual site setups, and allows for all aspects of a store to be offered in multiple languages.</p><p>The full setup steps for a multilingual site in Concrete CMS is outside the scope of the documentation, but the steps to add a new language to a site generally are as follows:</p><ul><li>Visit <strong>System &amp; Settings / Multilingual / Multilingual Setup</strong> within the Dashboard</li><li>Select <strong>Add Locale</strong>, and configure a new language/tree</li><li>Visit <strong>System &amp; Settings / Multilingual / Copy Languages</strong> within the same section of the Dashboard</li><li>Copy the default language tree into the new language</li><li>A <strong>Switch Language</strong> block is generally then added to a global area on the site</li></ul><p>Once performed, there will be new copies of the <code>/cart</code>, <code>/checkout</code> and <code>/checkout/complete</code> pages within the new language&#39;s sitemap. Product pages will also be duplicated.</p><p>Therefore, when adding further languages in the future, ensure that you perform the <strong>Copy Locale Tree</strong> action after adding.</p><p>When new products are added, Community Store will create the required copies of the product page in the different language trees of your site.</p><p>The setup means that a customer can view a product in the site, swap language to see a translated version of the product, and can progress through all steps of the checkout in their chosen language.</p><h3 id="store-translations" tabindex="-1">Store Translations <a class="header-anchor" href="#store-translations" aria-label="Permalink to &quot;Store Translations&quot;">​</a></h3><p>Translations of product details and other common pieces of text are performed via the <strong>Store / Multilingual</strong> section of the Dashboard.</p><h3 id="languages-and-orders" tabindex="-1">Languages and orders <a class="header-anchor" href="#languages-and-orders" aria-label="Permalink to &quot;Languages and orders&quot;">​</a></h3><p>When an order is placed the language used by the customer at the time is recorded against the order. This means that if an order receipt is re-sent via the Dashboard, the email will send in the language that the order was placed.</p>',12)])])}const c=t(l,[["render",i]]);export{p as __pageData,c as default};
